        return int(fruit.split()[0])

    apples = extract_fruit_count(s.split(" and ")[0])
    oranges = extract_fruit_count(s.split(" and ")[1].split()[0])

    total_fruits = n
    mango_fruits = total_fruits - apples - oranges

    return mango_fruits

